#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT HAnim : 1

Viewpoint {
  description "front"
  position 0 1 6
}

DEF H HAnimHumanoid {
  skeleton DEF J HAnimJoint {
    name "humanoid_root"
    children [
      DEF S HAnimSite {
        name "x_pt"
        translation 1 0 0
        children Shape {
          geometry Box {
            size 0.4 0.4 0.4
          }
        }
      }
      DEF SEG HAnimSegment {
        name "seg"
        children Shape {
          appearance Appearance {
            material Material {
              diffuseColor 1 0 0
            }
          }
          geometry Sphere {
            radius 0.3
          }
        }
      }
      Shape {
        geometry Cone { }
      }
    ]
  }
  joints USE J
  segments USE SEG
  sites USE S
  viewpoints DEF HS HAnimSite {
    name "cam_pt"
    translation 0 1 4
    children Viewpoint {
      description "site view"
    }
  }
}

